insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 80, 'B3.2.17', 'Účetní jednotka použije všechny výše uvedené informace, aby vykázala transakci následovně: Má dáti Dal Původní aktivum — 9,000 Aktivum uznané k podřízení nebo zbytkový podíl 1,000 — Aktivum k přijatému protiplnění ve formě zbytkového úroku 40 — Hospodářský výsledek (zisk z převodu) — 90 Závazek — 1,065 Přijaté peněžní prostředky 9,115 — Celkem 10,155 10,155 Okamžitě po transakci činí účetní hodnota aktiva 2,040 MJ, což je částka skládající se z 1,000 MJ, tj. rozdělené pořizovací náklady zadržené části, a z 1,040 MJ, což je dodatečná přetrvávající angažovanost účetní jednotky vyplývající z podřízení zadrženého podílu za úvěrové ztráty (což zahrnuje zbytkový úrok v hodnotě 40 MJ). V dalších účetních obdobích účetní jednotka uznává přijaté protiplnění za zkvalitnění úvěrového aktiva (65 MJ) na bázi časového rozlišení, akumuluje úrok z uznaného aktiva s použitím metody efektivní úrokové míry a uznává každou ztrátu ze znehodnocení uznaných aktiv. Jak se o ztrátě ze znehodnocení úvěrového aktiva účtuje, si můžeme ukázat na následujícím příkladu: předpokládejme, že v následujícím roce vznikne ztráta ze znehodnocení podkladových úvěrů ve výši 300 MJ. Účetní jednotka sníží uznané aktivum o 600 MJ (300 MJ se vztahuje k zadrženému podílu a 300 MJ k dodatečné přetrvávající angažovanosti, která vzniká z podřízení zadrženého podílu z důvodu ztrát ze znehodnocení) a uznaný závazek sníží o 300 MJ. Čistým výsledkem je zaúčtování částky 300 MJ, která představuje ztrátu ze znehodnocení, do nákladů. Vynětí finančních závazků (oddíl 3.3)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 81, 'B3.3.1', 'a) splní svůj závazek (nebo jeho část) tím, že věřiteli uhradí, obvykle hotovostí, jiným finančním aktivem, zbožím nebo službami, nebo b) je právně zproštěn své povinnosti uhradit závazek, a to buď na základě výsledku soudního řízení, nebo z rozhodnutí věřitele. (Tato podmínka může být splněna i v případě, že dlužník poskytne záruku.)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 82, 'B3.3.7', 'a) uznává nový finanční závazek rovnající se reálné hodnotě závazku dlužníka vyplývajícího ze záruky a b) uznává zisk nebo ztrátu, a to na základě rozdílu mezi i) veškerými přijatými platbami a ii) účetní hodnotou původního finančního závazku sníženou o reálnou hodnotu nového finančního závazku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 83, 'KLASIFIKACE (KAPITOLA 4)', 'Klasifikace finančních aktiv (oddíl 4.1) Obchodní model účetní jednotky pro řízení finančních aktiv'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 84, 'B4.1.2B', 'a) jak je hodnocena výkonnost obchodního modelu a finančních aktiv držených v rámci tohoto obchodního modelu a jak jsou předkládány klíčovému vedení účetní jednotky; b) rizika, která ovlivňují výkonnost obchodního modelu (a finančních aktiv držených v rámci tohoto obchodního modelu), a zejména způsob, jakým jsou tato rizika řízena, a c) jak jsou odměňováni manažeři podniku (například zda jsou odměny založeny na reálné hodnotě řízených aktiv nebo na inkasovaných smluvních peněžních tocích). Obchodní model, jehož cílem je držení aktiv za účelem inkasa smluvních peněžních toků'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 85, 'B4.1.4', 'Příklad Analýza Příklad 1 Účetní jednotka drží investice za účelem inkasa jejich smluvních peněžních toků. Potřeby financování účetní jednotky jsou předvídatelné a splatnost jejích finančních aktiv je přiřazena odhadovaným potřebám financování účetní jednotky. Účetní jednotka provádí činnosti v oblasti řízení úvěrového rizika s cílem minimalizovat úvěrové ztráty. V minulosti k prodejům obvykle docházelo v případě, kdy se úvěrové riziko finančních aktiv zvýšilo natolik, že daná aktiva již nesplňovala úvěrová kritéria uvedená v dokumentovaných investičních pravidlech účetní jednotky. Navíc došlo k nepříliš častým prodejům v důsledku neočekávaných finančních potřeb. Zprávy klíčovému vedení se zaměřují na úvěrovou kvalitu finančních aktiv a na smluvní návratnost. Účetní jednotka rovněž kromě jiných informací sleduje reálné hodnoty finančních aktiv.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 86, 'B4.1.4', 'Ačkoliv účetní jednotka bere v úvahu kromě jiných informací i reálné hodnoty finančních aktiv z hlediska likvidity (tj. částku peněžních prostředků, která by byla realizována, pokud by účetní jednotka potřebovala aktiva prodat), jejím cílem je držet finanční aktiva za účelem inkasa smluvních peněžních toků. Prodeje by nebyly s tímto cílem v rozporu, pokud by k nim došlo v reakci na zvýšení úvěrového rizika těchto aktiv, například v případě, že by tato aktiva již nesplňovala úvěrová kritéria uvedená v dokumentovaných investičních pravidlech účetní jednotky. V rozporu s tímto cílem by nebyly ani nepříliš časté prodeje vyplývající z nepředvídaných potřeb financování (např. při zátěžovém scénáři), ani kdyby hodnota těchto prodejů byla podstatná. Příklad 2 Obchodním modelem účetní jednotky je nákup portfolií finančních aktiv, například úvěrů. Tato portfolia mohou nebo nemusí zahrnovat finanční aktiva, která jsou úvěrově znehodnocena. Pokud tyto úvěry nejsou spláceny včas, účetní jednotka se pokusí realizovat smluvní peněžní toky různými prostředky, například kontaktuje dlužníka dopisem, telefonicky nebo jinými metodami. Cílem účetní jednotky je inkaso smluvních peněžních toků a účetní jednotka neřídí žádné úvěry v tomto portfoliu s cílem realizovat peněžní toky jejich prodejem. V některých případech účetní jednotka uzavírá úrokové swapy s cílem změnit úrokovou míru určitých finančních aktiv v portfoliu z pohyblivé úrokové míry na pevnou úrokovou míru. Cílem obchodního modelu účetní jednotky je držet finanční aktiva za účelem inkasa smluvních peněžních toků.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 87, 'B4.1.4', 'Stejná analýza by se uplatnila i v případě, že účetní jednotka nepředpokládá, že obdrží všechny smluvní peněžní toky (např. některá finanční aktiva jsou při prvotním uznání úvěrově znehodnocena). Kromě toho skutečnost, že účetní jednotka uzavírá transakce s deriváty s cílem změnit peněžní toky v rámci portfolia, sama o sobě nemění obchodní model účetní jednotky. Příklad 3 Cílem obchodního modelu účetní jednotky je poskytovat úvěry zákazníkům a následně prodávat tyto úvěry sekuritizačním subjektům. Sekuritizační subjekt vydává nástroje investorům. Poskytující účetní jednotka ovládá sekuritizační subjekt, a proto jej konsoliduje. Sekuritizační subjekt inkasuje smluvní peněžní toky z úvěrů a předává je svým investorům. Pro účely tohoto příkladu se předpokládá, že tyto úvěry se i nadále uznávají v konsolidovaném výkazu o finanční pozici, protože je sekuritizační subjekt nevyjímá. Konsolidovaná skupina poskytla úvěry s cílem držet je za účelem inkasa smluvních peněžních toků. Cílem poskytující účetní jednotky však je realizace peněžních toků z úvěrového portfolia prodejem úvěrů sekuritizačnímu subjektu, takže pro účely její samostatné účetní závěrky by se nejednalo o řízení tohoto portfolia za účelem inkasa smluvních peněžních toků. Příklad 4 Finanční instituce drží finanční aktiva za účelem plnění potřeby likvidních prostředků při „zátěžovém scénáři“ (např. „útoku“ klientů na bankovní vklady). Účetní jednotka nepředpokládá prodej těchto aktiv s výjimkou uvedených scénářů.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 88, 'B4.1.4', 'Účetní jednotka sleduje úvěrovou kvalitu těchto finančních aktiv a jejím cílem při jejich řízení je inkaso smluvních peněžních toků. Účetní jednotka hodnotí výkonnost těchto aktiv na základě získaných úrokových výnosů a realizovaných úvěrových ztrát. Účetní jednotka však rovněž sleduje reálnou hodnotu těchto finančních aktiv z hlediska likvidity s cílem zajistit, aby výše peněžních prostředků, která by byla realizována, pokud by účetní jednotka potřebovala aktiva prodat v důsledku zátěžového scénáře, byla dostačující pro uspokojení potřeb likvidity účetní jednotky. Účetní jednotka pravidelně realizuje prodeje, jejichž hodnota je nepodstatná, s cílem prokázat likviditu. Cílem obchodního modelu účetní jednotky je držet finanční aktiva za účelem inkasa smluvních peněžních toků. Tato analýza by se nezměnila ani v případě, že by účetní jednotka během předchozího zátěžového scénáře provedla prodeje s podstatnou hodnotou s cílem uspokojit své potřeby likvidních prostředků. Obdobně platí, že opakované prodejní činnosti, jejichž hodnota není podstatná, nejsou v rozporu s držením finančních aktiv za účelem inkasa smluvních peněžních toků. Jestliže však účetní jednotka drží finanční aktiva za účelem splnění svých každodenních potřeb likvidních prostředků a splnění tohoto cíle zahrnuje časté prodeje, jejichž hodnota je podstatná, není cílem obchodního modelu účetní jednotky držet finanční aktiva za účelem inkasa smluvních peněžních toků.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 89, 'B4.1.4', 'Obdobně platí, že pokud příslušný regulátor vyžaduje, aby účetní jednotka běžně prodávala finanční aktiva s cílem prokázat, že tato aktiva jsou likvidní, a hodnota prodaných aktiv je podstatná, není cílem obchodního modelu účetní jednotky držet finanční aktiva za účelem inkasa smluvních peněžních toků. Pro tuto analýzu není relevantní, zda je prodej finančních aktiv požadavkem uloženým třetí stranou, či zda ho účetní jednotka provede dle vlastního uvážení. Obchodní model, jehož cíle je dosaženo jak inkasem smluvních peněžních toků, tak prodejem finančních aktiv'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 90, 'B4.1.4C', 'Příklad Analýza Příklad 5 Účetní jednotka předpokládá, že jí za několik let vzniknou výdaje na dlouhodobá hmotná a nehmotná aktiva. Tato účetní jednotka investuje své přebytečné peněžní prostředky do krátkodobých a dlouhodobých finančních aktiv, aby mohla v případě potřeby financovat příslušné výdaje. Řada těchto finančních aktiv má smluvně sjednanou dobu splatnosti, která překračuje předpokládané investiční období účetní jednotky. Účetní jednotka bude držet finanční aktiva za účelem inkasa smluvních peněžních toků, a když nastane příležitost, prodá finanční aktiva s cílem reinvestovat peněžní prostředky do finančních aktiv s vyšším výnosem. Manažeři odpovědní za portfolio jsou odměňováni na základě celkových výnosů vytvořených daným portfoliem. Cíle tohoto obchodního modelu je dosaženo jak inkasem smluvních peněžních toků, tak prodejem finančních aktiv. Účetní jednotka bude průběžně rozhodovat o tom, zda inkaso smluvních peněžních toků nebo prodej finančních aktiv povede k maximalizaci výnosu z portfolia, dokud nenastane potřeba investovaných peněžních prostředků.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 91, 'B4.1.4C', 'Naproti tomu si představme účetní jednotku, která předpokládá peněžní odtok v horizontu pěti let s cílem financovat výdaje na dlouhodobá hmotná a nehmotná aktiva a investuje přebytečné peněžní prostředky do krátkodobých finančních aktiv. Když nastane splatnost těchto investic, účetní jednotka reinvestuje dané peněžní prostředky do nových krátkodobých finančních aktiv. Účetní jednotka zachovává tuto strategii, dokud nenastane potřeba finančních prostředků, a pak použije výnosy ze splatných finančních aktiv k financování výdajů na dlouhodobá hmotná a nehmotná aktiva. Před splatností dochází pouze k prodejům, jejichž hodnota není podstatná (pokud nedojde ke zvýšení úvěrového rizika). Cílem tohoto kontrastního obchodního modelu účetní jednotky je držet finanční aktiva za účelem inkasa smluvních peněžních toků. Příklad 6 Finanční instituce drží finanční aktiva s cílem pokrýt své každodenní potřeby likvidních prostředků. Účetní jednotka se snaží minimalizovat náklady na řízení těchto potřeb likvidních prostředků, a proto aktivně řídí výnosy z portfolia. Tyto výnosy se skládají jak z inkasa smluvních plateb, tak ze zisků a ztrát z prodeje finančních aktiv. Výsledkem je, že účetní jednotka drží finanční aktiva za účelem inkasa smluvních peněžních toků a prodává finanční aktiva za účelem reinvestic do finančních aktiv s vyšším výnosem nebo lepšího přiřazení trvání svých závazků. V minulosti docházelo v důsledku této strategie k častým prodejním činnostem a hodnota těchto prodejů byla podstatná. Předpokládá se, že tato činnost bude v budoucnosti pokračovat.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 92, 'B4.1.4C', 'Cílem tohoto obchodního modelu je maximalizovat výnos z portfolia za účelem pokrytí každodenních potřeb likvidních prostředků a účetní jednotka tohoto cíle dosahuje jak inkasem smluvních peněžních toků, tak prodejem finančních aktiv. Jinými slovy, jak inkaso smluvních peněžních toků, tak prodej finančních aktiv jsou nedílnou součástí dosahování cíle tohoto obchodního modelu. Příklad 7 Pojistitel drží finanční aktiva s cílem financovat závazky z pojistných smluv. Pojistitel používá výnosy ze smluvních peněžních toků z finančních aktiv k vypořádání svých splatných závazků z pojistných smluv. Aby zajistil, že smluvní peněžní toky z finančních aktiv jsou pro vypořádání těchto závazků dostatečné, pojistitel pravidelně provozuje podstatnou nákupní a prodejní činnost s cílem nově vyvážit své portfolio aktiv a naplňovat vznikající potřeby peněžních toků. Cílem tohoto obchodního modelu je financovat závazky z pojistných smluv. Pro dosažení tohoto cíle účetní jednotka inkasuje splatné smluvní peněžní toky a prodává finanční aktiva s cílem zachovat žádoucí profil portfolia aktiv. Jak inkaso smluvních peněžních toků, tak prodej finančních aktiv jsou proto nedílnou součástí dosahování cíle tohoto obchodního modelu. Jiné obchodní modely'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 93, 'B4.1.6', 'Smluvní peněžní toky, které jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 94, 'B4.1.9', 'Protiplnění za časovou hodnotu peněz'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 95, 'B4.1.9E', 'Smluvní podmínky,které mění časový rozvrh nebo výši smluvních peněžních toků'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 96, 'B4.1.11', 'a) pohyblivá úroková míra, která zahrnuje protiplnění za časovou hodnotu peněz, úvěrové riziko spojené s nesplacenou částkou jistiny za konkrétní časové období (protiplnění za úvěrové riziko může být stanoveno pouze při prvotním uznání a může být proto pevné) a další základní rizika a náklady poskytování úvěrů, jakož i ziskovou marži; b) smluvní podmínka, která umožňuje emitentovi (tj. dlužníkovi) předčasně splatit dluhový nástroj nebo umožňuje držiteli (tj. věřiteli) prodat dluhový nástroj emitentovi zpět před splatností a předčasně splacená částka v podstatě představuje nesplacené částky jistiny a úroky z nesplacené částky jistiny, které mohou obsahovat přiměřenou kompenzaci za dřívější ukončení smlouvy; c) smluvní podmínka, která umožňuje emitentovi nebo držiteli prodloužit smluvní splatnost dluhového nástroje (tj. opce na prodloužení), a podmínky opce na prodloužení mají za následek, že smluvní peněžní toky v období prodloužení jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny, které mohou obsahovat přiměřenou dodatečnou kompenzaci za prodloužení smlouvy.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 97, 'B4.1.12', 'a) účetní jednotka pořídí nebo vydá finanční aktivum s prémií nebo diskontem oproti smluvní jmenovité hodnotě; b) výše předčasné splátky představuje v podstatě částku smluvní jmenovité hodnoty a časově rozlišený (ale neuhrazený) smluvní úrok, který může obsahovat přiměřenou kompenzaci za dřívější ukončení smlouvy; c) v době, kdy účetní jednotka provede prvotní uznání finančního aktiva, není reálná hodnota prvku předčasného splacení podstatná.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 98, 'B4.1.13', 'Nástroj Analýza Nástroj A Nástroj A je a dluhopis s uvedeným datem splatnosti. Splátky jistiny a úroků z nesplacené částky jistiny jsou vázány na index inflace měny, ve které je daný nástroj vydán. Vazba na inflaci nemá pákový efekt a jistina je chráněna. Tyto smluvní peněžní toky jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny. Vazba splátek jistiny a úroků z nesplacené částky jistiny na index inflace, který nevyužívá pákový efekt, upravuje časovou hodnotu peněz na současnou úroveň. Jinými slovy úroková míra daného nástroje odráží „skutečný“ úrok. Výše úroku tak představuje protiplnění za časovou hodnotu peněz nesplacené částky jistiny. Jestliže však byly úrokové platby indexovány k jiné proměnné jako třeba k výkonnosti dlužníka (např. čistý zisk dlužníka) nebo ke kapitálovému indexu, nejsou smluvní peněžní toky splátkami jistiny a úroků z nesplacené částky jistiny (s výjimkou případů, kdy je výsledkem indexování k výkonnosti dlužníka úprava, která pouze kompenzuje držiteli změny úvěrového rizika daného nástroje, takže smluvní peněžní toky jsou pouze splátkami jistiny a úroků). Je tomu tak proto, že smluvní peněžní toky odrážejí výnos, který je v rozporu se základním ujednáním o úvěrech (viz bod B4.1.7A). Nástroj B Nástroj B je nástrojem s pohyblivou úrokovou mírou s uvedeným datem splatnosti, které umožňuje dlužníkovi průběžně si volit tržní úrokovou míru. Dlužník si například může ke každému datu úpravy úrokové míry zvolit, že bude hradit tříměsíční LIBOR po dobu tří měsíců nebo jednoměsíční LIBOR po dobu jednoho měsíce.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 99, 'B4.1.13', 'Smluvní peněžní toky jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny, pokud úrok placený po celou dobu trvání nástroje odráží protiplnění za časovou hodnotu peněz, za úvěrové riziko spojené s daným nástrojem a za další základní rizika a náklady poskytování úvěrů, jakož i ziskovou marži (viz odstavec B4.1.7A). Skutečnost, že úroková míra LIBOR je upravována v průběhu doby trvání nástroje, sama o sobě tento nástroj nevylučuje. Jestliže si však dlužník může zvolit, že bude hradit jednoměsíční úrokovou míru, která je upravována každé tři měsíce, je tato úroková míra upravována s takovou četností, která neodpovídá době její platnosti. V důsledku toho dochází k modifikaci prvku časové hodnoty peněz. Obdobně v případě, že má nástroj smluvní úrokovou míru založenou na splatnosti, která může překročit zbývající dobu trvání daného nástroje (například jestliže nástroj s pětiletou splatností má pohyblivou míru, která je pravidelně upravována, ale vždy odráží pětiletou splatnost), dochází k modifikaci prvku časové hodnoty peněz. Je tomu tak proto, že úrok splatný v jednotlivých obdobích je oddělen od úrokového období. V takových případech musí účetní jednotka kvalitativně nebo kvantitativně porovnat smluvní peněžní toky s nástrojem, který je identický ve všech ohledech s výjimkou toho, že doba platnosti úrokové míry odpovídá úrokovému období, aby se stanovilo, zda jsou peněžní toky pouze splátkami jistiny a úroků z nesplacené částky jistiny. (Avšak viz odstavec B4.1.9E, který poskytuje vodítko ohledně úrokových měr.)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 100, 'B4.1.13', 'Například při posuzování dluhopisu s pětiletou splatností a s pohyblivou úrokovou mírou, která je upravována každých šest měsíců, ale která vždy odráží pětiletou splatnost, účetní jednotka vezme v úvahu smluvní peněžní toky z nástroje, který je upravován každých šest měsíců na šestiměsíční úrokovou míru, avšak ve zbývajících ohledech je totožný. Stejná analýza by se uplatnila, pokud by měl dlužník možnost volit mezi různými publikovanými úrokovými mírami věřitele (např. dlužník má možnost volit mezi publikovanou jednoměsíční pohyblivou úrokovou mírou a publikovanou tříměsíční pohyblivou úrokovou mírou věřitele). Nástroj C Nástroj C je dluhopis s uvedeným datem splatnosti a s pohyblivou tržní úrokovou mírou. Tato pohyblivá úroková míra je zastropována. Smluvní peněžní toky: a) nástroje s pevnou úrokovou mírou i b) nástroje s pohyblivou úrokovou mírou jsou splátkami jistiny a úroků z nesplacené částky jistiny, pokud úrok odráží protiplnění za časovou hodnotu peněz, za časovou hodnotu peněz, za úvěrové riziko spojené s daným nástrojem po dobu trvání tohoto nástroje a za další základní rizika a náklady poskytování úvěrů, jakož i ziskovou marži. (Viz odstavec B4.1.7A.)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 101, 'B4.1.13', 'V důsledku toho může mít nástroj, který je kombinací a) a b) (např. dluhopis se zastropovanou úrokovou mírou) peněžní toky, které jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny. Taková smluvní podmínka může snížit pohyblivost peněžních toků nastavením limitu pohyblivé úrokové míry (např. horního nebo dolního limitu úrokové míry) nebo zvýšit pohyblivost peněžních toků v důsledku změny pevné míry v pohyblivou. Nástroj D Nástroj D je úvěr s právem plného postihu a je zajištěn kolaterálem. Skutečnost, že úvěr s právem plného postihu je zajištěn kolaterálem, sama o sobě nemá vliv na analýzu toho, zda smluvní peněžní toky jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny. Nástroj E Nástroj E vydává regulovaná banka a má uvedené datum splatnosti. Tento nástroj má pevnou úrokovou míru a všechny smluvní peněžní toky jsou nevolitelné. Emitent však podléhá právním předpisům, které umožňují nebo vyžadují, aby vnitrostátní orgány příslušné k řešení za určitých okolností nařídily držitelům určitých nástrojů akceptovat snížení jejich hodnoty, včetně nástroje E. Vnitrostátní orgán příslušný k řešení má například pravomoc snížit jmenovitou hodnotu nástroje E nebo jej přeměnit na pevný počet kmenových akcií emitenta, pokud konstatuje, že emitent čelí vážným finančním obtížím, nastala u něj potřeba dodatečného regulatorního kapitálu nebo je „v selhání.“'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 102, 'B4.1.13', 'Držitel by provedl analýzu smluvních podmínek finančního nástroje s cílem určit, zda dávají vzniknout peněžním tokům, které jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny, a jsou proto v souladu se základním ujednáním o úvěrech. Tato analýza by nebrala v úvahu platby vzniklé pouze v důsledku pravomoci vnitrostátního orgánu příslušného k řešení nařídit ztráty držitelům nástroje E. Je tomu tak proto, že tato pravomoc a výsledné platby nejsou smluvními podmínkami finančního nástroje. Naproti tomu smluvní peněžní toky by nebyly pouze splátkami jistiny a úroků z nesplacené částky jistiny, jestliže smluvní podmínky finančního nástroje umožňují nebo vyžadují, aby ztráty držiteli nařídil emitent nebo jiná účetní jednotka (např. snížením jmenovité hodnoty nebo přeměnou daného nástroje na pevný počet kmenových akcií), pokud jsou tyto smluvní podmínky genuinní, i v případě, že pravděpodobnost, že dojde k nařízení takové ztráty, je nízká.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 103, 'B4.1.14', 'Nástroj Analýza Nástroj F Nástroj F je dluhopis, který je konvertibilní na pevný počet kapitálových nástrojů emitenta. Držitel by provedl analýzu konvertibilního dluhopisu v plném rozsahu. Smluvní peněžní toky nejsou splátkami jistiny a úroků z nesplacené částky jistiny, protože odrážejí výnosy, které jsou v rozporu se základním ujednáním o úvěrech (viz odstavec B4.1.7A); tj. výnosy jsou vázány na hodnotu vlastního kapitálu emitenta. Nástroj G Nástroj G je úvěr s inverzní pohyblivou úrokovou mírou (tj. tato úroková míra má inverzní vztah k tržním úrokovým mírám). Tyto smluvní peněžní toky nejsou pouze splátkami jistiny a úroků z nesplacené částky jistiny. Výše úroku nepředstavuje protiplnění za časovou hodnotu peněz nesplacené částky jistiny. Nástroj H Nástroj H je perpetuita, ale emitent může tento nástroj kdykoli odkoupit a uhradit držiteli jeho jmenovitou hodnotu zvýšenou o dlužný úrok. Nástroj H má tržní úrokovou míru, ale platbu úroků nelze provést, pokud emitent není bezprostředně poté schopen dostát svým závazkům. Z odloženého úroku se nepočítá další naběhlý úrok. Tyto smluvní peněžní toky nejsou splátkami jistiny a úroků z nesplacené částky jistiny. Je tomu tak proto, že může být nutné, aby emitent odložil úrokové platby, a z částky těchto odložených úroků se již neakumulují další úroky. V důsledku této skutečnosti výše úroku nepředstavuje protiplnění za časovou hodnotu peněz nesplacené částky jistiny. Pokud u odložených částek došlo k jejich nárůstu o naběhlý úrok, mohly by být smluvní peněžní toky splátkami jistiny a úroků z nesplacené částky jistiny.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 104, 'B4.1.14', 'Skutečnost, že nástroj H je perpetuita, sama o sobě neznamená, že smluvní peněžní toky nejsou splátkami jistiny a úroků z nesplacené částky jistiny. Perpetuita má v podstatě kontinuální (vícenásobné) opce na prodloužení. V důsledku takových opcí mohou vzniknout smluvní peněžní toky, které jsou splátkami jistiny a úroků z nesplacené částky jistiny, jestliže jsou úrokové platby povinné a musí být placeny po neomezenou dobu. Rovněž skutečnost, že nástroj H je možné předčasně splatit, neznamená, že smluvní peněžní toky nejsou splátkami jistiny a úroků z nesplacené částky jistiny, pokud není svolatelný za částku, která podstatně neodráží splátku nesplacené jistiny a úroků z této nesplacené částky jistiny. I v případě, že svolatelná částka zahrnuje částku, která představuje přiměřenou náhradu držiteli za dřívější ukončení nástroje, by smluvní peněžní toky mohly být splátkami jistiny a úroků z nesplacené částky jistiny. (Viz též odstavec B4.1.12).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 105, 'B4.1.19', 'Smluvně propojené nástroje'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 106, 'B4.1.21', 'a) smluvní podmínky tranše posuzované za účelem klasifikace (bez přezkumu podkladového portfolia finančních nástrojů) dávají vzniknout peněžním tokům, které jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny (např. úroková míra tranše není vázána na komoditní index); b) podkladové portfolio finančních nástrojů má znaky peněžních toků uvedenou v odstavcích B4.1.23 a B4.1.24 a c) míra vystavení úvěrovému riziku u podkladového portfolia finančních nástrojů obsažených v dané tranši je stejná nebo nižší než míra vystavení úvěrovému riziku u podkladového portfolia finančních nástrojů (například úvěrový rating tranše, která je posuzována pro účely klasifikace, je stejný nebo vyšší než úvěrový rating, který by se uplatnil na jedinou tranši financující celé podkladové portfolio finančních nástrojů).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 107, 'B4.1.24', 'a) snižují volatilitu peněžních toků u nástrojů uvedených v odstavci B4.1.23 a ve spojení s nástroji uvedenými v odstavci B4.1.23 jsou jejich výsledkem peněžní toky, které jsou pouze splátkami jistiny a úroků z nesplacené částky jistiny (např. horní nebo dolní limit úrokové míry nebo smlouva, která snižuje úvěrové riziko některých nebo všech nástrojů uvedených v odstavci B4.1.23), nebo b) vyrovnávají peněžní toky tranší s peněžními toky portfolia podkladových nástrojů uvedených v odstavci B4.1.23 s cílem řešit rozdíly pouze v následujících aspektech: i) zda je úroková míra pevná nebo pohyblivá; ii) měna, ve které jsou peněžní toky vyjádřeny, včetně inflace této měny, nebo iii) časování peněžních toků.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 108, 'B4.1.26', 'Možnost určit finanční aktivum nebo finanční závazek jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku (oddíly 4.1 a 4.2)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 109, 'B4.1.28', 'Zařazení vylučuje nebo podstatně omezuje účetní neshodu'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 110, 'B4.1.30', 'a) účetní jednotka má smlouvy spadající do rozsahu působnosti IFRS 17, jejichž ocenění odráží aktuální informace, a finanční aktiva, která považuje za související a jež by jinak byla oceněna buď reálnou hodnotou do ostatního úplného výsledku, nebo naběhlou hodnotou; b) účetní jednotka má finanční aktiva, finanční závazky nebo obojí, které sdílejí stejný druh rizika, jako například úrokové riziko, z nějž plynou opačné změny reálné hodnoty, které se obvykle navzájem kompenzují. Ale jen některé z těchto nástrojů by byly oceňovány reálnou hodnotou do hospodářského výsledku (například ty, které jsou deriváty nebo jsou klasifikovány jako určené k obchodování). Může se také stát, že požadavky zajišťovacího účetnictví nejsou splněny, například proto, že nejsou splněny požadavky na efektivnost zajištění v odstavci 6.4.1;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 111, 'B4.1.30', 'c) účetní jednotka má finanční aktiva, finanční závazky nebo obojí, které sdílejí stejný druh rizika, jako například úrokové riziko, z nějž plynou opačné změny reálné hodnoty, které se obvykle navzájem kompenzují, a žádné z těchto finančních aktiv nebo finančních závazků nesplňuje požadavky pro určení jako zajišťovací nástroj, protože nejsou zaúčtovány v reálné hodnotě do hospodářského výsledku. Navíc v důsledku toho, že není použito zajišťovací účetnictví, dochází k podstatnému nesouladu při uznání zisků a ztrát. Účetní jednotka například financovala specifickou skupinu úvěrů vydáním obchodovatelných dluhopisů, jejichž změny reálné hodnoty se obvykle navzájem kompenzují. Pokud navíc účetní jednotka pravidelně nakupuje a prodává dluhopisy, ale zřídka nebo vůbec neobchoduje s úvěry, vykázání jak úvěrů, tak dluhopisů reálnou hodnotou do hospodářského výsledku odstraní nesoulad, který by jinak vznikl, pokud by byly obě položky oceněny naběhlou hodnotou a při každém dalším nákupu dluhopisu by byl uznán zisk nebo ztráta.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 112, 'B4.1.32', 'Skupina finančních závazků nebo finančních aktiv a finančních závazků je řízena a její výkonnost je hodnocena na základě reálné hodnoty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 113, 'B4.1.36', 'Vložené deriváty (oddíl 4.3)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 114, 'B4.3.5', 'a) prodejní opce vložená do nástroje, která umožňuje držiteli požadovat po emitentovi, aby nástroj koupil zpět za peněžní částku nebo jiná aktiva, a jejíž hodnota se mění v závislosti na změně ceny akcií nebo komodity nebo v závislosti na kapitálovém nebo komoditním indexu, úzce nesouvisí s hostitelským dluhovým nástrojem; b) opce nebo automatické ustanovení týkající se prodloužení splatnosti dluhového nástroje úzce nesouvisí s hostitelskou úvěrovou smlouvou, pokud souběžně s prodloužením splatnosti nedochází k úpravě tržní úrokové míry. Pokud účetní jednotka vydá dluhový nástroj a držitel tohoto dluhového nástroje k němu prodá kupní opci určenou třetí straně, pak emitent považuje kupní opci za faktor, který prodlužuje splatnost dluhového nástroje za předpokladu, že emitent může být v důsledku uplatnění kupní opce požádán, aby se podílel na opětovném uvedení dluhového nástroje na trh (nebo tomuto uvedení napomohl); c) úroky nebo splátky jistiny vázané na kapitálový index a vložené do hostitelského dluhového nástroje nebo pojistné smlouvy – jimiž se výše úroku nebo jistiny přepočítává podle indexu kapitálového nástroje – úzce nesouvisejí s hostitelským nástrojem, protože rizika vlastní hostitelskému nástroji a vloženému derivátu jsou různá;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 115, 'B4.3.5', 'd) úroky nebo splátky jistiny přepočítané vázané na komoditní index a vložené do hostitelského dluhového nástroje nebo pojistné smlouvy – jimiž se výše úroku nebo jistiny přepočítává podle indexu příslušné komodity (např. zlata) – úzce nesouvisejí s hostitelským nástrojem, protože rizika vlastní hostitelskému nástroji a vloženému derivátu jsou různá; e) kupní opce, prodejní opce nebo opce předčasného splacení vložená do hostitelského dluhového nástroje nebo do hostitelské pojistné smlouvy úzce nesouvisí s hostitelským nástrojem, pokud: i) se realizační cena opce ke každému datu uplatnění opce přibližně nerovná naběhlé hodnotě hostitelského dluhového nástroje nebo účetní hodnotě hostitelské pojistné smlouvy nebo ii) realizační cena opce předčasného splacení neuhrazuje věřiteli částku až do výše přibližné současné hodnoty ušlého úroku za zbývající dobou trvání hostitelského nástroje. Ušlý úrok je součinem předčasně splacené jistiny a diferenciálu úrokové míry. Diferenciál úrokové míry představuje přebytek efektivní úrokové míry hostitelského nástroje nad efektivní úrokovou mírou, kterou by účetní jednotka získala ke dni předčasného splacení za předpokladu, že by znovu investovala předplacenou jistinu do podobného nástroje po zbývající dobu trvání hostitelské smlouvy. Nejprve se zhodnotí, zda kupní opce nebo prodejní opce úzce souvisí s hostitelským dluhovým nástrojem, a poté se oddělí složka vlastního kapitálu konvertibilního dluhového nástroje podle standardu IAS 32;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 116, 'B4.3.5', 'f) úvěrové deriváty, které jsou vloženy do hostitelského dluhového nástroje a které jedné ze stran („příjemci“) umožňují převést úvěrové riziko související s daným referenčním aktivem, ať už je tato strana ve skutečnosti vlastní, či nikoliv, na jinou stranu (na „ručitele“), úzce nesouvisejí s hostitelským dluhovým nástrojem. Tyto úvěrové deriváty umožňují ručiteli, aby na sebe převzal úvěrové riziko související s daným aktivem bez jeho koupě.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 117, 'B4.3.8', 'a) vložený derivát, v němž podstatnou roli hraje úroková míra nebo index úrokové míry, který může změnit výši úroku, jenž by jinak byl placen nebo získán z úročeného hostitelského dluhového nástroje, nebo pojistná smlouva úzce souvisí s hostitelským nástrojem, vyjma případů, kdy hybridní smlouva nemůže být vyrovnána tak, že držitel nezíská zpět v podstatě celou svou uznanou investici, nebo vložený derivát může alespoň zdvojnásobit držitelovu počáteční míru návratnosti z hostitelské smlouvy a může mít za následek míru návratnosti, která je přinejmenším dvojnásobná ve srovnání s tržní mírou, která by byla dosažena u smlouvy se stejnými podmínkami, jako má hostitelská smlouva; b) vložený horní nebo dolní limit úrokové míry dluhového nástroje úzce souvisí s hostitelským dluhovým nástrojem, pokud horní limit úrokové míry je stejný nebo vyšší než tržní úroková míra a dolní limit úrokové míry je stejný nebo nižší než tržní úroková míra při emisi nástroje a pokud se u vývoje horního nebo dolního limitu úrokové míry neuplatňuje pákový efekt. Stejně tak ustanovení obsažená ve smlouvě o koupi nebo prodeji aktiva (např. komodity), která určují horní nebo dolní limit ceny, jež bude zaplacena nebo získána za aktivum, úzce souvisejí s hostitelskou smlouvou, pokud jak horní, tak dolní limit ceny byly od počátku „mimo peníze“ a neuplatňuje se u nich pákový efekt;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 118, 'B4.3.8', 'c) vložený měnový derivát, který poskytuje platbu jistiny nebo úroku v cizí měně a je vložený do hostitelského dluhového nástroje (například do duální měnové obligace), úzce souvisí s hostitelským dluhovým nástrojem. Tento derivát se neodděluje od hostitelského nástroje, protože podle IAS 21 Dopady změn měnových kurzů je třeba uznat kurzové zisky a ztráty z celé peněžní položky do hospodářského výsledku. d) vložený měnový derivát v hostitelské smlouvě, která je pojistnou smlouvou nebo není finančním nástrojem (jako např. smlouva o koupi nebo prodeji nefinanční položky v cizí měně), úzce souvisí s hostitelskou smlouvou za předpokladu, že se u něj neuplatňuje pákový efekt, neobsahuje opční komponentu a vyžaduje platby vyjádřené v jedné z těchto měn: i) ve funkční měně kterékoliv významné smluvní strany; ii) v měně, v níž je cena daného zboží nebo služby, které jsou pořízeny nebo doručeny, obvykle vyjádřena při obchodních transakcích ve světě (např. v US dolarech za transakce s ropou), nebo iii) v měně, která je běžně používána ve smlouvách o koupi nebo prodeji nefinančních položek v ekonomickém prostředí, ve kterém se transakce odehrává (např. relativně stabilní a likvidní měna, která se běžně používá při místních obchodních transakcích nebo v zahraničním obchodě);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 119, 'B4.3.8', 'e) vložená opce předčasného splacení, která je vložena do stripu úroků nebo stripu jistiny, úzce souvisí s hostitelskou smlouvou za předpokladu, že hostitelská smlouva i) původně vznikla v důsledku oddělení práva na peněžní toky plynoucí z finančního nástroje, jenž neobsahoval vložený derivát, a ii) neobsahuje žádné podmínky, které nebyly zakotveny již v původním hostitelském dluhovém nástroji; f) vložený derivát u leasingových smluv úzce souvisí s hostitelskou smlouvou, pokud jsou jím i) index odrážející inflaci, např. index splátek pronájmu v poměru k indexu spotřebitelských cen (za předpokladu, že pronájem není financován třetí stranou a že index odráží inflaci ekonomiky, v níž daná účetní jednotka působí; ii) variabilní splátky pronájmu na základě souvisejících tržeb nebo iii) variabilní splátky pronájmu na základě měnící se úrokové míry; g) prvek, který výši plnění váže na hodnotu podílové jednotky („unit-linking feature“) a který je vložen do hostitelského nástroje nebo hostitelské pojistné smlouvy, úzce souvisí s hostitelským nástrojem nebo hostitelskou smlouvou, pokud jsou platby vázané na podílovou jednotku oceněny její současnou hodnotou, která odráží reálnou hodnotu aktiv fondu. „Unit-linking feature“ je smluvní podmínka, která výši plnění váže na hodnotu podílových jednotek interního nebo externího investičního fondu;')
